"""Tests for scripts/make_locks.py (allowlist, hashes, headers, --check LF normalization)."""

from __future__ import annotations

import os
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

SCRIPTS_DIR = Path(__file__).resolve().parent.parent
if str(SCRIPTS_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPTS_DIR))

import make_locks  # noqa: E402

_VALID_CPU_LOCK_BODY = """\
# This file was autogenerated by uv via the following command:
#    python scripts/make_locks.py
filelock==4.2.10 \\
    --hash=sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa
    # via torch
    # from https://pypi.org/simple
torch==2.14.1+cpu \\
    --hash=sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb
    # via -r packs/torch-cpu-smoke/requirements.in
    # from https://download.pytorch.org/whl/cpu
"""


class TestMakeLocks(unittest.TestCase):
    def test_valid_lock_passes_and_triton_allowed(self) -> None:
        cu_body = (
            _VALID_CPU_LOCK_BODY
            + """\
triton==3.2.0 \\
    --hash=sha256:cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    # via torch
    # from https://download.pytorch.org/whl/cu126
"""
        )
        make_locks.validate_lock_content(cu_body)

    def test_non_allowlisted_package_from_pytorch_index_fails(self) -> None:
        bad = (
            _VALID_CPU_LOCK_BODY
            + """\
filelock-extra==1.0.0 \\
    --hash=sha256:dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd
    # via torch
    # from https://download.pytorch.org/whl/cu126
"""
        )
        with self.assertRaises(make_locks.LockValidationError) as ctx:
            make_locks.validate_lock_content(bad)
        self.assertIn("outside allowlist", str(ctx.exception))

    def test_torch_from_pypi_fails(self) -> None:
        bad = """\
torch==2.14.1 \\
    --hash=sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb
    # via -r requirements.in
    # from https://pypi.org/simple
"""
        with self.assertRaises(make_locks.LockValidationError) as ctx:
            make_locks.validate_lock_content(bad)
        self.assertIn("must resolve from PyTorch index", str(ctx.exception))

    def test_missing_hash_fails(self) -> None:
        bad = """\
torch==2.14.1+cpu
    # via -r requirements.in
    # from https://download.pytorch.org/whl/cpu
"""
        with self.assertRaises(make_locks.LockValidationError) as ctx:
            make_locks.validate_lock_content(bad)
        self.assertIn("missing --hash=sha256", str(ctx.exception))

    def test_render_lock_headers_have_measured_required_bytes_x_1_2(self) -> None:
        rendered = make_locks.render_lock_text(
            _VALID_CPU_LOCK_BODY, os_name="windows", backend="cu126"
        )
        lines = rendered.splitlines()
        self.assertEqual(lines[0], "# skald-backend: cu126")
        self.assertEqual(lines[1], f"# skald-required-bytes: {int(4326 * 1_000_000 * 1.2)}")

    def test_build_uv_env_strips_other_uv_vars_and_keeps_proxy_and_ssl(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            cache_dir = Path(tmp) / "uv-cache"
            base = {
                "PATH": "/usr/bin",
                "HTTPS_PROXY": "http://127.0.0.1:8888",
                "HTTP_PROXY": "http://127.0.0.1:8888",
                "NO_PROXY": "localhost",
                "SSL_CERT_FILE": "/etc/ssl/proxy.pem",
                "UV_INDEX_URL": "https://evil.example/simple",
                "UV_EXTRA_INDEX_URL": "https://extra.example/simple",
                "UV_OFFLINE": "1",
            }
            env = make_locks.build_uv_env(uv_cache_dir=cache_dir, base_env=base)
            self.assertEqual(env["UV_NO_CONFIG"], "1")
            self.assertEqual(env["UV_CACHE_DIR"], str(cache_dir))
            self.assertEqual(env["UV_LINK_MODE"], "hardlink")
            self.assertEqual(env["UV_PYTHON_DOWNLOADS"], "never")
            self.assertEqual(env["UV_SYSTEM_CERTS"], "1")
            self.assertEqual(env["UV_NO_PROGRESS"], "1")
            self.assertNotIn("UV_INDEX_URL", env)
            self.assertNotIn("UV_EXTRA_INDEX_URL", env)
            self.assertNotIn("UV_OFFLINE", env)
            self.assertEqual(env["HTTPS_PROXY"], "http://127.0.0.1:8888")
            self.assertEqual(env["SSL_CERT_FILE"], "/etc/ssl/proxy.pem")

    def test_check_mode_lf_normalises_and_detects_drift(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            packs_dir = tmp_path / "packs"
            pack_dir = packs_dir / "torch-cpu-smoke"
            (pack_dir / "locks").mkdir(parents=True)
            (pack_dir / "requirements.in").write_text(
                "# skald-backends: cpu\ntorch==2.14.1\n", encoding="utf-8"
            )
            fake_uv = tmp_path / "uv"
            fake_uv.write_text("stub", encoding="utf-8")

            def fake_compile(
                _uv: Path, _req: Path, os_name: str, backend: str, **_kwargs: object
            ) -> bytes:
                return make_locks.render_lock_text(
                    _VALID_CPU_LOCK_BODY, os_name=os_name, backend=backend
                ).encode("utf-8")

            with mock.patch.object(make_locks, "compile_lock", side_effect=fake_compile):
                # Write locks first
                rc = make_locks.process_packs(
                    packs_dir=packs_dir,
                    check=False,
                    uv_bin=fake_uv,
                    uv_cache_dir=tmp_path / "uv-cache",
                )
                self.assertEqual(rc, 0)

                # Simulate Windows core.autocrlf=true checking out CRLF on disk
                win_lock = pack_dir / "locks" / "windows-cpu.txt"
                win_lock.write_bytes(win_lock.read_bytes().replace(b"\n", b"\r\n"))

                rc_check = make_locks.process_packs(
                    packs_dir=packs_dir,
                    check=True,
                    uv_bin=fake_uv,
                    uv_cache_dir=tmp_path / "uv-cache",
                )
                self.assertEqual(rc_check, 0)

                # Introduce real content drift
                win_lock.write_bytes(win_lock.read_bytes().replace(b"4.2.10", b"4.2.11"))
                rc_drift = make_locks.process_packs(
                    packs_dir=packs_dir,
                    check=True,
                    uv_bin=fake_uv,
                    uv_cache_dir=tmp_path / "uv-cache",
                )
                self.assertEqual(rc_drift, 1)


if __name__ == "__main__":
    unittest.main()
